def transform(grid):
    H, W = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 1:
                row2s = [i for i in range(W) if grid[r][i] == 2]
                col2s = [i for i in range(H) if grid[i][c] == 2]
                if (any(i < c for i in row2s) and any(i > c for i in row2s)) or \
                   (any(i < r for i in col2s) and any(i > r for i in col2s)):
                    out[r][c] = 3
    return out
